INSERT INTO public.game_cards(category,game_number,prompt) SELECT category,game_number, CASE game_number WHEN 4 THEN 'Act out '||topic||' without words; the crew guesses the story, then you tell the real context.' WHEN 7 THEN 'Invent a snack inspired by '||topic||'; describe three ingredients and let the crew guess the dish.' WHEN 8 THEN 'Show a gesture inspired by '||topic||'; the crew mirrors it and adds a safe move.' WHEN 11 THEN 'Describe '||topic||' with three clues and let the crew guess the place, price or phrase.' ELSE 'Pitch a low-cost idea for '||topic||'; the crew asks one question about your budget.' END FROM (SELECT g.game_number,c.category,t.topic FROM (VALUES(4),(7),(8),(11),(15)) g(game_number) CROSS JOIN (VALUES('travel'),('food')) c(category) CROSS JOIN (VALUES('a squad memory'),('a public street performance'),('a famous sports moment'),('a cultural festival in {destination}'),('an art form from {destination}'),('a local phrase'),('a favorite public view'),('a skill learned on a trip'),('a local specialty'),('a colorful market'),('a music tradition'),('a public celebration')) t(topic)) seed;